    std::set<Point2d, comparators::Point2dComparator> uniqueIntersections;

    // Iterate over all pairs of segments
    for (size_t i = 0; i < segments.size(); ++i) {
        for (size_t j = i + 1; j < segments.size(); ++j) {
            const Segment2d& seg1 = segments[i];
            const Segment2d& seg2 = segments[j];

            // Use CGAL to compute intersection
            CK_Segment_2 cgalSeg1(CK_Point_2(seg1.p1().x(), seg1.p1().y()), 
                                  CK_Point_2(seg1.p2().x(), seg1.p2().y()));
            CK_Segment_2 cgalSeg2(CK_Point_2(seg2.p1().x(), seg2.p1().y()), 
                                  CK_Point_2(seg2.p2().x(), seg2.p2().y()));

            auto intersectionResult = CGAL::intersection(cgalSeg1, cgalSeg2);

            if (intersectionResult) {
                if (const CK_Point_2* point = boost::get<CK_Point_2>(&*intersectionResult)) {
                    // Single point intersection
                    Point2d p(point->x(), point->y());
                    if (uniqueIntersections.find(p) == uniqueIntersections.end()) {
                        intersections.push_back(p);
                        uniqueIntersections.insert(p);
                    }
                }
                else if (const CK_Segment_2* seg = boost::get<CK_Segment_2>(&*intersectionResult)) {
                    // Overlapping segment - add both endpoints
                    Point2d p1(seg->source().x(), seg->source().y());
                    Point2d p2(seg->target().x(), seg->target().y());

                    if (uniqueIntersections.find(p1) == uniqueIntersections.end()) {
                        intersections.push_back(p1);
                        uniqueIntersections.insert(p1);
                    }
                    if (uniqueIntersections.find(p2) == uniqueIntersections.end()) {
                        intersections.push_back(p2);
                        uniqueIntersections.insert(p2);
                    }
                }
            }
        }
    }

    return intersections;
